unitsize(2mm); defaultpen(linewidth(.8pt));
fill((0,0)--(0,5)--(5,5)--cycle,gray);
fill((25,0)--(25,5)--(20,5)--cycle,gray);
draw((0,0)--(0,5)--(25,5)--(25,0)--cycle);
draw((0,0)--(5,5));
draw((20,5)--(25,0));
[/asy]

